from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.models import Payment
from ledgerly.support import process_refund_request
from ledgerly.errors import BillingError
from ledgerly import audit

T0 = datetime(2026,1,1,tzinfo=timezone.utc)
def mk(status="captured", amt="100.00"):
    return Payment("pay_1","inv_1",Decimal(amt),status=status,created_at=T0,captured_at=T0)

# rounding
p=mk(); process_refund_request(p,"49.999","u",T0); print("round:",p.refunded_amount)
# full refund status
p=mk(); process_refund_request(p,"100.00","u",T0); print("full:",p.refunded_amount,p.status)
# partial then full
p=mk(); process_refund_request(p,"40.00","u",T0); process_refund_request(p,"60.00","u",T0); print("partial+full:",p.refunded_amount,p.status)
# over refund
p=mk(); process_refund_request(p,"40.00","u",T0)
try: process_refund_request(p,"70.00","u",T0)
except BillingError as e: print("over:",e.code)
# non-captured
for st in ("authorized","voided","refunded"):
    try: process_refund_request(mk(st),"1.00","u",T0)
    except BillingError as e: print(st,"->",e.code)
# non-positive
for a in ("0","-1.00"):
    try: process_refund_request(mk(),a,"u",T0)
    except BillingError as e: print(a,"->",e.code)
# audit
print("audit:",audit.events("payment_refunded"))
EOF"}

